typedef struct {
    const char        *name;
    const char *const *packages;
} Registry;

static const Registry REGISTRIES[] = {
    { "pip",   PIP_TOP },
    { "npm",   NPM_TOP },
    { "cargo", CARGO_TOP },
    { "go",    GO_TOP },
    { "gem",   GEM_TOP },
    { NULL, NULL }
};

/* Known typosquat attack patterns:
 * - Character swap: requsets → requests
 * - Missing char: reqests → requests
 * - Extra char: requestss → requests
 * - Hyphen confusion: python-dateutil vs python_dateutil
 * - Scope confusion: @types/lodash vs types-lodash              */
static int
normalize_pkg_name(const char *src, char *dst, size_t cap) {
    size_t i, j = 0;
    for (i = 0; src[i] && j < cap - 1; i++) {
        char c = src[i];
        /* Normalize: underscore → hyphen, strip whitespace */
        if (c == '_') c = '-';
        if (c == ' ' || c == '\t') continue;
        dst[j++] = (c >= 'A' && c <= 'Z') ? c + 32 : c;
    }
    dst[j] = '\0';
    return (int)j;
}

PackageVerdict
hlse_check_package(const char *pkg_name, const char *ecosystem) {
    PackageVerdict v;
    char norm[128];
    int ri;
    const char *eco_canon;

    memset(&v, 0, sizeof(v));
    int best_dist = 99, best_idx = -1;

    if (!pkg_name || !pkg_name[0]) return v;
    normalize_pkg_name(pkg_name, norm, sizeof(norm));
    eco_canon = canonical_ecosystem(ecosystem);

    for (ri = 0; REGISTRIES[ri].name; ri++) {
        const char *const *pkgs;
        int pi;

        /* Filter by ecosystem when the caller named a recognized one. An
         * unrecognized alias yields eco_canon == NULL → scan every registry
         * (fail safe) rather than silently matching nothing.              */
        if (eco_canon && strcmp(eco_canon, REGISTRIES[ri].name) != 0)
            continue;

        pkgs = REGISTRIES[ri].packages;
        for (pi = 0; pkgs[pi]; pi++) {
            char norm_ref[128];
            int dist;

            normalize_pkg_name(pkgs[pi], norm_ref, sizeof(norm_ref));

            /* Exact match → safe. Record WHICH registry recognised it: the
             * caller uses a non-empty reason here to tell "known-good name"
             * apart from "name I have never heard of". Both are score 0 with
             * 0 matches, but they carry very different residual risk — see the
             * package blind-spot text in hlse_core.c. */
            if (strcmp(norm, norm_ref) == 0) {
                v.score = 0;
                v.n_matches = 0;
                snprintf(v.reason, sizeof(v.reason),
                         "Known package: '%s' is a recognised %s package.",
                         pkgs[pi], REGISTRIES[ri].name);
                hlse_sanitize_display(v.reason);
                return v;
            }

            dist = dl_distance(norm, norm_ref);
            /* dist 1-2: typosquat band. dist 3: slopsquat advisory — a
             * name that close to a top package but absent from the
             * snapshot is exactly where AI-hallucinated names land and
             * where attackers register them. Low score: LOG, not ALERT. */
            if (dist <= 3 && dist > 0 &&
                v.n_matches < HLSE_SUPPLY_MAX_MATCHES)
            {
                int score_add = (dist == 1) ? 50 : (dist == 2) ? 35 : 15;
                snprintf(v.matches[v.n_matches].legit_name,
                         sizeof(v.matches[0].legit_name), "%s", pkgs[pi]);
                snprintf(v.matches[v.n_matches].registry,
                         sizeof(v.matches[0].registry), "%s",
                         REGISTRIES[ri].name);
                v.matches[v.n_matches].distance = dist;
                v.n_matches++;
                if (dist < best_dist) { best_dist = dist; best_idx = v.n_matches - 1; }

                if (score_add > v.score) v.score = score_add;
            }
        }
    }

    /* Amplifier: a single distance-1 neighbour and NO other dist≤2 match →
     * very likely typosquat. Dist-3 slopsquat matches are advisory only:
     * they must not dilute the amplifier (reqeusts ~ requests@1 plus a
     * reqwest@3 still fires) nor inflate the near-match count that gates
     * it (reqests ~ requests@1 + reqwest@2 stays at the 2-match ALERT
     * band). */
    {
        int n_close = 0, i;
        for (i = 0; i < v.n_matches; i++)
            if (v.matches[i].distance <= 2) n_close++;
        if (n_close == 1 && best_dist == 1) {
            v.score = 70;
            snprintf(v.reason, sizeof(v.reason),
                     "Typosquat alert: '%s' is 1 edit from '%s' (%s). "
                     "Did you mean '%s'?",
                     pkg_name, v.matches[best_idx].legit_name,
                     v.matches[best_idx].registry,
                     v.matches[best_idx].legit_name);
        } else if (v.n_matches > 0 && best_dist == 3) {
            snprintf(v.reason, sizeof(v.reason),
                     "Slopsquat candidate: '%s' is 3 edits from '%s' (%s) and "
                     "not a known package — AI-hallucinated names are "
                     "predictable attacker registrations; verify it exists "
                     "before installing",
                     pkg_name, v.matches[best_idx].legit_name,
                     v.matches[best_idx].registry);
        } else if (v.n_matches > 0) {
            snprintf(v.reason, sizeof(v.reason),
                     "Possible typosquat: '%s' is close to %d known package(s)",
                     pkg_name, v.n_matches);
        }
    }

    if (v.score > 100) v.score = 100;
    /* Reason text embeds the caller-supplied package name. */
    hlse_sanitize_display(v.reason);
    return v;
}

/* ═══════════════════════════════════════════════════════════════════════
 * S2: Pastejacking Detection
 *
 * Detects hostile content in text that a user copies from the web:
 *
 *   P1. Hidden newlines    — executes before user can review
 *   P2. curl|bash patterns — remote code execution
 *   P3. Unicode control    — right-to-left override, zero-width chars
 *   P4. Sudo/su injection  — privilege escalation in pasted command
 *   P5. Encoded payloads   — base64 -d | sh, python -c "..."
 *   P6. History evasion    — commands starting with space (bash)
 *   P7. Background exec    — trailing & hides process
 *   P8. Windows LOLBin     — "ClickFix" PowerShell/mshta/certutil one-liners
 * ═══════════════════════════════════════════════════════════════════════ */

/* Single-needle case-insensitive match — delegates to the shared
 * implementation; `needle` must be lowercase ASCII.                 */
static int
ci_contains(const char *hay, const char *needle) {
    return hlse_ci_contains(hay, needle);
}

/* Token-prefix variant: the needle (bare lowercase ASCII alnum — an
 * executable/tool name) must start at a token boundary: preceded by a
 * non-alphanumeric byte or sitting at the string start. The right
 * side stays open so tool FAMILY members with version/name suffixes
 * still match ("phast"→phastCons, "nix"→nixos-rebuild, "boinc"→
 * boinctui) — matching the corpus's deliberate prefix-family design.
 * Mid-word matches are rejected: "nix" cannot fire inside "unix"/
 * "phoenix", "rye" inside "dryer", "just" inside "adjust".       */
static int
ci_contains_tok(const char *hay, const char *needle) {
    const char *p = hay;
    size_t nl;
    if (!hay || !needle) return 0;
    nl = strlen(needle);
    if (nl == 0) return 1;
    for (; *p; p++) {
        size_t k = 0;
        while (k < nl && p[k] &&
               (char)tolower((unsigned char)p[k]) == needle[k])
            k++;
        if (k == nl && (p == hay || !isalnum((unsigned char)p[-1])))
            return 1;
    }
    return 0;
}

/* Any-needle matcher — delegates to the shared hlse_str_any (see
 * hlse_util.c); needles are case-sensitive strstr() literals.       */
static int
hay_any(const char *hay, const char *const needles[]) {
    return hlse_str_any(hay, needles);
}

/* 'fetch', 'ncat', 'netcat' are matched via ci_contains_tok in the
 * P2/P12b gates instead — the substring forms fired inside
 * 'prefetch ', 'concat ', 'mincat ' (real FP).                    */
/* 'ssh' mention that is not part of a '.ssh' path — the ci table
 * cannot tell '.ssh' (directory) from the ssh(1) tool name, and the
 * tunnel-flag arm cross-fired on any copy tool's '-r' flag next to
 * a .ssh path (cp -r ~/.ssh → 55).  Dot-prefixed occurrences are
 * path components, not the tool; everything else (autossh, sshd,
 * ssh-keygen, ...) keeps old substring behaviour.                 */
static int
has_ssh_ref(const char *text) {
    const char *p;
    if (!text) return 0;
    for (p = text; p[0] && p[1] && p[2]; p++)
        if ((p[0] == 's' || p[0] == 'S') &&
            (p[1] == 's' || p[1] == 'S') &&
            (p[2] == 'h' || p[2] == 'H') &&
            (p == text || p[-1] != '.'))
            return 1;
    return 0;
}

/* Bulk copy of a credential directory — cp/scp/rsync/tar/zip/mv of
 * .ssh/.aws/.gnupg/.kube/.docker/... is the classic staging step
 * before exfiltration.  '.ssh'-dir copies previously detected only
 * by accident (the ssh-tunnel cross-fire above); this arm makes the
 * coverage deliberate and extends it to the other credential dirs.
 * Single files (id_rsa, .aws/credentials) already hit CRED_PATHS.   */
static const char *CRED_COPY_TOOLS[] = {
    "cp", "scp", "pscp", "rsync", "mv", "tar", "zip", "7z",
    "xcopy", "robocopy", "ditto", "rar", "cpio", "zipcloak", NULL
};
static const char *CRED_DIRS[] = {
    ".ssh", ".aws", ".gnupg", ".gpg", ".kube", ".docker",
    ".azure", ".m2", ".config/gcloud", ".config/gh",
    ".config\\gcloud", ".config\\gh", ".cargo", ".composer",
    ".huggingface", ".s3cfg", ".config/rclone", ".config\\rclone",
    ".terraform.d", ".config\\azure", ".minikube", NULL
};
/* case-insensitive strstr — needle must be lowercase ASCII       */
static const char *
ci_find(const char *hay, const char *needle) {
    size_t nl;
    if (!hay || !needle) return NULL;
    nl = strlen(needle);
    for (; *hay; hay++) {
        size_t k = 0;
        while (k < nl && hay[k] &&
               (char)tolower((unsigned char)hay[k]) == needle[k])
            k++;
        if (k == nl) return hay;
    }
    return NULL;
}

/* The dir name appears as a copy operand — '.ssh' itself, '.ssh/'
 * or '.ssh/ *' (glob) — not as a file path inside it
 * ('.ssh/config.bak'), which is routine admin and pinned benign.  */
static int
is_dir_operand(const char *m, const char *needle) {
    const char *s = m + strlen(needle);
    if (*s == '\0' || *s == ' ' || *s == '\t')
        return 1;
    if (*s == '/' || *s == '\\') {
        s++;
        if (*s == '\0' || *s == '*' || *s == ' ' || *s == '\t' ||
            *s == '.')
            return 1;
    }
    return 0;
}
static int
cred_dir_copy(const char *text) {
    int i, j;
    for (i = 0; CRED_COPY_TOOLS[i]; i++)
        if (ci_contains_tok(text, CRED_COPY_TOOLS[i])) {
            for (j = 0; CRED_DIRS[j]; j++) {
                const char *m = text;
                size_t nl = strlen(CRED_DIRS[j]);
                while ((m = ci_find(m, CRED_DIRS[j])) != NULL) {
                    if (is_dir_operand(m, CRED_DIRS[j]))
                        return 1;
                    m += nl;
                }
            }
            return 0;
        }
    return 0;
}

